        if (grBrandParent.next()) {
            var brandParentID = grBrandParent.sys_id;

            var grBrandTask = new GlideRecord('x_asscs_allos_o2c_task');
            grBrandTask.addEncodedQuery('parent=' + brandParentID + '^order=3'); // parent=6044310d3b839e104a3b3537f4e45a0e^order=3
            grBrandTask.query();

            if (grBrandTask.next()) {

                var brandCode = grBrandTask.getValue('u_codigo_marca');
