    getDadosLocatario: function(id) {

        var brandParentID = id;

        var grClienteTaskPrincipal = new GlideRecord('x_asscs_allos_o2c_task');
        grClienteTaskPrincipal.addEncodedQuery('parent=' + brandParentID + '^order=14');
        grClienteTaskPrincipal.query();
        if (grClienteTaskPrincipal.next()) {

            var locatarioVerificacao = grClienteTaskPrincipal.getValue('tipo_de_pessoa_locatario');

            if (locatarioVerificacao) {

                var possuiCodLoc = grClienteTaskPrincipal.getValue('cliente_possui_cadastro_sap_locatario');

                var obj_Locatario = '';

                if (possuiCodLoc == 'sim') {

                    if (locatarioVerificacao == 'fisica') {

                        obj_Locatario = {
                            locatarioCPF: grClienteTaskPrincipal.getValue('cpf_locatario_nova_loc'),
                            possuiCadastroLocatario: grClienteTaskPrincipal.getValue('cliente_possui_cadastro_sap_locatario'),
                            codigoSAPLocatario: grClienteTaskPrincipal.getValue('codigo_bp_sap_locatario')
                        };
                        return obj_Locatario;
                    } else if (locatarioVerificacao == 'juridica') {
                        obj_Locatario = {
                            locatarioCNPJ: grClienteTaskPrincipal.getValue('cnpj_locatario_nova_loc'),
                            possuiCadastroLocatario: grClienteTaskPrincipal.getValue('cliente_possui_cadastro_sap_locatario'),
